#include "stdafx.h"#include "DLAY.h"KDLAY::KDLAY(): m_CurParameterID(-1), m_ReadParams( 0 ){}static LPCSTR s_MyParameters[]={  "On/Off Delay Mode",};BOOL KDLAY::OnParsingSingleText( std::string &szText, RECTL *rc ){  if( m_CurParameterID!=-1 )  {    CStringA s;    if( 7==m_CurParameterID )      s.Format( "DisableValue = %s", szText.c_str() );    if( !s.IsEmpty() )      m_settings.push_back( s.GetBuffer() );    AddParam( s_MyParameters[m_CurParameterID], szText.c_str() );    m_CurParameterID = -1;    m_ReadParams++;    return TRUE;//сделать преобразование параметра к виду, пригодному для формирования исполняемого кода  }  for( int i=0; i<_countof(s_MyParameters); i++ )  {    if( szText.find(s_MyParameters[i])==0 )    {      m_CurParameterID = i;      return TRUE;    }  }  return FALSE;}